quests[8881] = { id = 8881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Raketenbündel" }
quests[8882] = { id = 8882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zünder für Raketenbündel" }
quests[8883] = { id = 8883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valadar Sternensang", description = "Jetzt, da Ihr in Besitz der Mondfesteinladung seid, könntet Ihr doch einmal zur Mondlichtung reisen - Ihr werdet dort viele Feiernde vorfinden! In Nachthafen erwarten Valadar Sternensang und seine Schwester Fariel bereits diejenigen, die die Feierlichkeiten kaum erwarten können.\n\nReist zur Mondlichtung mithilfe des Mondlichts und sprecht mit Valadar Sternensang; schaut Euch um und erfahrt welche Preise Ihr während des Fests gewinnen könnt!", sourceObjective = "Verwendet die Mondfesteinladung im Mondlicht und reist somit zur Mondlichtung. Sprecht nach Eurer Ankunft in Nachthafen mit Valadar Sternensang.", completion = "{name}, willkommen in Nachthafen, Gastgeber des Mondfests! Wenngleich unser Dorf normalerweise etwas entlegen und abgesondert von den Bewohnern Azeroths liegt, so öffnen wir während der Festtage doch allen unsere Arme und Herzen.\n\nAmüsiert Euch gut, solange Ihr hier seid, {name}, und sprecht wieder mit mir oder meiner Schwester, wenn Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[8884] = { id = 8884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischköpfe, Fischköpfe...", description = "Seid gegrüßt, {class}. Was, frage ich Euch, könnt Ihr erkennen, wenn Ihr in Richtung Küste seht? Richtig, unser Strand... unsere Stille Küste wurde vom Übel, den Murlocs, befallen.\n\nDieser Makel darf nicht bestehen bleiben!\n\nIch habe eine Aufgabe für Euch. Solltet Ihr bereit dazu sein, so würde ich ihre Köpfe haben wollen! Mal sehen, ob wir ihre Zahl derart verringern können, dass sie nicht mehr anders können, als in die dunklen Tiefen zurückzukehren, aus denen sie gekommen sind!", sourceObjective = "Sammelt 8 Köpfe von Grimmschuppenmurlocs und bringt sie zu Hathvelion Sonnenblick im Immersangwald auf der Klippe, die die Stille Küste überblickt.", progress = "Wir Waldläufer von der Zuflucht der Weltenwanderer haben uns der Wiedergutmachung aller Schäden gewidmet, die unser schönes Land so schrecklich verheert haben. Egal, wie lange es auch dauern mag.\n\nIch kann mich doch darauf verlassen, dass Ihr mit den Murlocköpfen zurückgekehrt seid, die ich von Euch verlangt habe?", completion = "Gute Arbeit, {class}. Dem Gestank nach zu urteilen, seid Ihr mit der von mir geforderten Beute zurückgekehrt, vielleicht sogar mit mehr. Ich bin mir sicher, dass wir dafür Verwendung haben werden, sei es in einem Eintopf oder etwas Ähnlichem.\n\nLeider scheinen Eure Bemühungen den Zweck nicht erfüllt zu haben; die Murlocs ziehen sich noch immer nicht zurück. Wir müssen noch tatkräftiger handeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[8885] = { id = 8885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mmmrrrgggllls Ring", description = "Die Grimmschuppenmurlocs haben sich durch Eure Taten nicht vertreiben lassen. Ich glaube aber zu wissen, was sie endlich in die Flucht schlagen wird, und wie ich mich gleichzeitig persönlich an ihnen rächen kann.\n\nSie haben einen Murlochäuptling, der sich selbst Mmmrrrggglll nennt. Er wandert entlang des Goldenen Strandes südlich der Flussmündung umher. Dies Biest hat einst einen meiner Kameraden getötet und trägt seitdem seinen Ring als offenes Zeichen der Verachtung und des Spotts.\n\nVernichtet Mmmrrrggglll und bringt mir den Ring meines Freundes wieder. Das sollte diese Monster ein für alle Mal einschüchtern!", sourceObjective = "Erlangt Mmmrrrgggllls Ring von dem Häuptling der Grimmschuppen und kehrt damit anschließend zu Hathvelion Sonnenblick im Immersangwald auf der Klippe, die die Stille Küste überblickt, zurück.", progress = "Ihr verhelft mir zu Erfolg und Rache, {class}. Habt Ihr den Ring?", completion = "Endlich! Die Grimmschuppen sind zwar noch immer nicht gewichen, wie erhofft, aber es war ein herrliches Schauspiel, als sie nach dem Tod ihres Anführers in Panik und Verwirrung umhergeirrt sind. Ihr habt meinen Dank und den der Sin'dorei von Silbermond!\n\nBitte, nehmt eine dieser Belohnungen für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8886] = { id = 8886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piraten der Grimmschuppen!", description = "Wie gut, dass Ihr hier seid, {class}! Diese schleimigen Grimmschuppenmurlocs haben meine Fracht gestohlen! Als wenn es nicht schon schlimm genug wäre, dass die Getriebenen mir meine letzten magischen Güter geraubt haben - und jetzt das! Was ist nur aus diesem Land geworden?\n\nKönnt Ihr mir meine Fracht wiederbeschaffen? Ich erwarte zwar nicht, dass Ihr alles zurückerlangt, bin aber für jedes Stück dankbar. Es waren die Grimmschuppenmurlocs in den Hütten im Westen, südlich des Ankerplatzes am Goldenen Strand. Ich bin mir ganz sicher!", sourceObjective = "Erlangt 6 Stücke von Kapitänin Kelisendras Fracht wieder und bringt sie zu Kapitänin Kelisendra beim befestigten Lager direkt östlich des Ankerplatzes der Sonnensegel im Immersangwald zurück.", progress = "Ich bin dankbar für die Unterstützung von jemandem wie Euch, {name}. Es stimmt mich fast schon wieder fröhlich. Allerdings erinnert es mich auch daran, was diese Monster meinem Schiff angetan haben und was mit Quel'Thalas geschieht.\n\nHabt Ihr es geschafft, Teile meiner Fracht wiederzuerlangen?", completion = "Ihr habt es geschafft! Ihr habt mich vor dem Ruin bewahrt und die scheußlichen Kreaturen meine Vergeltung spüren lassen!\n\nWenn ich es jetzt noch schaffe, dass mir diese hübschen Waldläufer mit meiner Fracht helfen, dann komme ich endlich weg von hier! Ich muss noch einmal zurückkehren, wenn Velendris die Schiffswerft zurückerobert hat.\n\nHier, nehmt diese Münze. Ich kann Euch leider nicht mehr geben, aber ich hoffe, es entlohnt Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8887] = { id = 8887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitänin Kelisendras verlorene Seekarten", description = "Interessant... was Ihr hier gefunden habt, ist eine wasserdichte Lederhülse, die ein paar Seiten Pergamentpapier enthält. Nach den Kennzeichnungen zu urteilen, handelt es sich eindeutig um Seekarten. Jede dieser Karten trägt das Siegel von Kapitänin Kelisendra.\n\nIhr habt sicher schon von einem kleinen, befestigten Lager östlich des nahegelegenen Ankerplatzes der Sonnensegel gehört. Vielleicht findet Ihr die Kapitänin ja dort?", sourceObjective = "Bringt Kapitänin Kelisendras verlorene Seekarten zu Kapitänin Kelisendra beim befestigten Lager direkt östlich des Ankerplatzes der Sonnensegel im Immersangwald zurück.", progress = "Hallo, {class}, Euer Anblick ist ein gutes Zeichen. Ich weiß, es ist verrückt, dass ich überhaupt hier bin, wo der Ankerplatz doch von den Getriebenen überfallen wurde. Velendris und seine Waldläufer haben geschworen mich zu beschützen, unter der Bedingung, dass ich von hier verschwinde, sobald ich meine Fracht wiedererlangt habe.\n\nWas habt Ihr da... das kommt mir so bekannt vor?", completion = "Oh, Ihr herzensguter, herzensguter {class}! Ich hatte ja keine Ahnung, dass diese widerlichen Grimmschuppenmurlocs auch noch meine Seekarten entwendet hatten! Ohne diese Karten hätte ich niemals wieder in See stechen können, sobald wir den Ankerplatz zurückerobert und das Schiff repariert haben.\n\nIch bin Euch zutiefst dankbar! Hier, nehmt diese Münze als Zeichen meiner Anerkennung.", sourceObjectiveStatus = "unverified-source-field" }
quests[8888] = { id = 8888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lehrling des Magisters", description = "{class}, hört Euch mein Anliegen an. Auf Grund von Dingen, die ich jetzt nicht weiter erklären kann, habe ich beschlossen, meine nahegelegene Schule zu schließen. Vor ein paar Tagen habe ich eine meiner Schülerinnen, Lehrling Loralthalis, mit diesem Auftrag dorthin geschickt. Seitdem habe ich nichts mehr von ihr gehört.\n\nWerdet Ihr zum Nachtschimmerturm gehen und nachsehen, ob alles mit ihr in Ordnung ist? Ihr werdet den Turm finden, indem Ihr dem Pfad, der von der Zuflucht der Weltenwanderer aus nach Norden führt, folgt und dann bei der Weggabelung rechts abbiegt.", sourceObjective = "Sprecht mit Lehrling Loralthalis nahe des Nachtschimmerturms im Immersangwald.", completion = "Der Magister sorgt sich um mein Wohlergehen? Wie süß von ihm; ich wünschte, er hätte ein derartiges Interesse etwas früher gezeigt, als wir noch im Turm waren.\n\nNaja, das tut jetzt nichts zur Sache. Hört gut zu, {class}, ich muss Euch um einen Gefallen bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8889] = { id = 8889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deaktivierung des Turms", description = "Wie Ihr wisst, hat mich Magister Nachtschimmer hierher zurückgeschickt, damit ich die Kraftquellen, die den Turm versorgen, deaktiviere. Es gibt drei davon, sie befinden sich an unterschiedlichen Stellen im Innern des Turms.\n\nUnglücklicherweise scheine ich zu spät zu sein, denn der Nachtschimmerturm wurde von seltsamen, magischen Kreaturen überrannt. Ich habe nicht das benötigte Wissen, um diese Aufgabe zu erfüllen, aber <ein/eine:c> {class} wie Ihr könnte es doch sicherlich ohne größere Probleme?", sourceObjective = "Deaktiviert 3 Kraftquellen des Nachtschimmerturms im Nachtschimmerturm. Bringt anschließend das Deaktivierungsjuwel zu Lehrling Loralthalis im Immersangwald.", progress = "Ich kann es aus dieser Entfernung nicht mit Sicherheit sagen... habt Ihr den Nachtschimmerturm bereits deaktiviert?", completion = "Ich bin Euch für Eure Hilfe dankbar, aber es betrübt mich zu hören, dass einige meiner Lehrlingsfreunde der Abhängigkeit verfallen sind.\n\nJetzt, da die Kraftquellen des Turms deaktiviert wurden, werde ich wohl noch eine Weile hier bleiben. Ich möchte sehen, ob sich die Lage beruhigt, damit ich mich hineinschleichen kann, um ihre Überreste zu bergen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8890] = { id = 8890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht vom Turm", description = "{name}, ich hätte noch eine letzte Bitte an Euch. Würdet Ihr Magister Nachtschimmer bei der Zuflucht der Weltenwanderer über die Ereignisse berichten, die hier vorgefallen sind? Sagt ihm, dass es mir gut geht, aber betont bitte auch, dass einige Lehrlinge zu Getriebenen geworden sind.\n\nVielen Dank für Eure Hilfe!", sourceObjective = "Kehrt zu Magister Nachtschimmer bei der Zuflucht der Weltenwanderer im Immersangwald zurück.", completion = "Nein! Ich war zu spät. Es ist alles meine Schuld.\n\nMeine Untersuchungen hinsichtlich der Aufbereitung alternativer Magiequellen sind mir außer Kontrolle geraten und ich konnte nichts mehr tun, was dies hätte aufhalten können. Wäre ich nur selbst gegangen... oder hätten sie auf mich gehört und meine Warnungen befolgt!\n\nMeine Hände sind mit Blut befleckt, {class}. Ich danke Euch dennoch, dass Ihr diese armen Seelen meiner ehemaligen Lehrlinge erlöst habt. Es ist ein kleiner Trost zu wissen, dass sie nicht länger in dem Zustand verweilen müssen, an dessen Stelle ein {race} besser tot wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[8891] = { id = 8891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgegebene Untersuchungen", description = "Ihr habt ein Buch mit Untersuchungsberichten gefunden, das offenbar von Magister Nachtschimmer zurückgelassen wurde. Ihr überfliegt rasch den Inhalt und stellt mit Entsetzen fest, dass man versucht hat, verderbte magische Ströme zu filtern, was womöglich eine Erklärung für die Ereignisse hier beim Nachtschimmerturm sein könnte. Der Magister möchte dies sicherlich zurück.", sourceObjective = "Bringt Magister Nachtschimmers Tagebuch zu Magister Nachtschimmer bei der Zuflucht der Weltenwanderer im Immersangwald zurück.", progress = "Was ist das? Es kommt mir bekannt vor. Oh nein, dieses Tagebuch... meine Untersuchungen... dies hat all die schrecklichen Ereignisse verursacht.", completion = "Hier ist er also, {name}, der Beweis für mein Verbrechen. Dieses Tagebuch enthält all meine schlecht durchdachten Studien.\n\nIch schenkte den Warnungen keine Beachtung und führte meine Untersuchungen fort, bis es schon fast zu spät war. Als ich endlich meine Fehler einsah, tat ich alles in meiner Macht Stehende. Allerdings sind einige meiner Schüler zu diesem Zeitpunkt bereits zu weit gegangen. Ich evakuierte den Turm, um sie vor der Verderbnis in Schutz zu bringen. Jedoch vergaß ich in meiner Eile, die Kraftquellen zu deaktivieren.\n\nIch werde diese Aufzeichnungen verbrennen, damit sie zukünftig keinen Schaden mehr anrichten können. Ich wollte den Sin'dorei doch nur helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8892] = { id = 8892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorfall beim Ankerplatz der Sonnensegel", description = "Der Ankerplatz der Sonnensegel wurde von einem Haufen Getriebener überrannt. Sobald wir Verstärkung erhalten, werden wir diesen Verbrechern schon zeigen, wer hier das Sagen hat, {name}.\n\nIn der Zwischenzeit könntet Ihr uns helfen, indem Ihr ihnen etwas Disziplin beibringt. Geht zu ihnen und macht deutlich, dass man mit uns keine Spielchen treibt. Der Ankerplatz der Sonnensegel liegt genau westlich von Morgenluft.", sourceObjective = "Tötet 5 getriebene Rohlinge und 5 getriebene Straßendiebe und erstattet Waldläufer Degolien im Immersangwald Bericht.", completion = "Das wird ihnen zeigen, dass man es sich mit uns besser nicht verscherzt. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8893] = { id = 8893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Super-Ei-o-Mat" }
quests[8894] = { id = 8894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Grunds", description = "Ich kann Euch sagen, es ist furchtbar! Seltsame Dinge gehen im Turm vor sich, der Magister und seine Lehrlinge sind weggelaufen und wie Ihr wisst, wurde der gesamte Grund von magischen Bestien überrannt! Und wer sagte Wyllithen Bescheid? Niemand, so sieht es aus!\n\n{class}, Ihr müsst mir helfen, hier wieder für Ordnung zu sorgen... ich kann nicht länger über den Grund wachen, solange diese 'Anomalien' hier in blinder Wut herumlaufen!", sourceObjective = "Tötet 6 Manaschlangen und 6 Ätherbestien. Kehrt anschließend zu Grundbewahrer Wyllithen beim Nachtschimmergrund im Immersangwald zurück.", progress = "Habt Ihr Euch darum gekümmert? Ist Euch eine ausreichende Zahl dieser magischen Anomalien zum Opfer gefallen? Was würde ich nur tun, wenn Magister Nachtschimmer zurückkäme und all diese Bestien wären noch hier?", completion = "Nun, ich denke, das dürfte fürs Erste genügen, oder nicht? Danke für die Hilfe, {class}. Ich hoffe nur, dass ich hier alles rechtzeitig absichern kann, bevor der Magister zum Nachtschimmerturm zurückkommt.\n\nNehmt dies bisschen Kleingeld; es ist nicht viel, aber ich habe im Moment nicht mehr. Ihr könnt ruhig noch ein paar Bestien mehr töten, wenn Ihr hier unterwegs seid, das wäre nett von Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[8895] = { id = 8895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an das Sanktum des Nordens", description = "Es freut mich, dass Ihr Euch zumindest in gewissen Hinsichten als fähig erweist, {name}. Ich gebe Euch eine weitere Aufgabe, da Ihr so begierig scheint, Euch beweisen zu wollen.\n\nDies ist ein Brief für Leybewahrer Caidanis, der Arkanist, der für die Aufrechterhaltung des Sanktums des Nordens verantwortlich ist. Geht vom Falkenplatz Richtung Südwesten und Ihr werdet ihn finden. Er ist eine sehr wichtige Persönlichkeit, ich hoffe also, dass Ihr ihn nicht mit zu belanglosem Geschwätz belästigt.", sourceObjective = "Überbringt den unbeschrifteten Brief an Leybewahrer Caidanis beim Sanktum des Nordens im Immersangwald.", progress = "Ja, {class}?", completion = "Vielen Dank, {name}. Ich habe diesen Brief bereits erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[8896] = { id = 8896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zwergenspion", description = "Seid Ihr sicher, dass Ihr diese Notizen bei einer Nachtelfe gefunden habt? Das meiste davon wurde in Zwergisch verfasst...\n\nAusgrabungsleiter Ambossel! Er wurde von Eisenschmiede wegen eines diplomatischen Auftrags hierher geschickt. Ich hätte es wissen müssen, sein Interesse an unseren arkanen Sankten war etwas zu groß. {name}, findet den Zwerg im Sanktum des Nordens und kümmert Euch um ihn. Oh, bitte geht diskret dabei vor.", sourceObjective = "Findet und tötet Ausgrabungsleiter Ambossel im Sanktum des Nordens und berichtet anschließend Aeldon Sonnenmal im Immersangwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[8897] = { id = 8897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Colara", description = "Wenn ich das Tor bewache muss ich ständig an meine geliebte Colara denken. Ich kann sie immer nur für ein paar kurze Stunden sehen, wenn ich Glück habe. Ach, seht mich doch an. Ich erhalte nur einen niederen Offizierssold und jeden Tag könnte ich an die Front abberufen werden.\n\nWürde sie mich dann einfach vergessen? Ich meine, es gibt so viele wohlhabende Männer in der Stadt.\n\nHier, ich habe einige Dinge aufgeschrieben... Nicht viel, aber vielleicht könntet Ihr diese Nachricht meiner Liebsten überbringen. Mein Dank wäre Euch gewiss.", sourceObjective = "Bringt Leutnant Heldrics sorgfältig verfasste Notiz zu Colara Dean außerhalb der Bank von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[8898] = { id = 8898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Colara", description = "Als ich geschäftlich mit der Bank in Sturmwind zu tun hatte, traf ich ein Mädchen. Sie hat mir auf Anhieb mein Herz gestohlen. Ich kann einfach nicht mehr aufhören, an sie zu denken! Ich würde Ihr gerne diese Nachricht schicken. Ganze Zwölfmal musste ich sie neu schreiben!\n\nJetzt möchte ich sicherstellen, dass sie meinen Brief auch erhält.\n\nVielleicht reist Ihr ja nach Sturmwind und könnt mir weiterhelfen?", sourceObjective = "Bringt den zerknitterten Brief zu Colara Dean außerhalb der Bank in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[8899] = { id = 8899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Colara", description = "Wie soll ich ihre Schönheit nur beschreiben? Tausende Jahre voll der Poesie und mir fehlen die Worte.\n\nDiese Sterblichen verwässern den Geist und am Ende bleiben wir als plappernde Narren zurück.\n\nZu lange habe ich diese Worte immer und immer wieder in mich aufgenommen. Es ist mir unmöglich, sie weiter zu verfeinern. Nein, sie muss diese Nachricht noch heute erhalten, oder ein anderer Verehrer wird sie für sich einnehmen.", sourceObjective = "Bringt den makellosen Brief zu Colara Dean außerhalb der Bank von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[8900] = { id = 8900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Elenia", description = "Sie war so traurig. Ich habe es genau gespürt, trotz Ihrer Versuche es zu verbergen. Ich meine, sie wirkte so traurig, versteht Ihr?\n\nDa war diese Verbindung zwischen uns beiden, als ich mit ihr sprach. Niemand hatte mich bisher verstanden, doch sie tat es auf Anhieb.\n\nAls ich es den anderen erzählte, lachten sie nur über mich und so habe ich nie wieder mit ihr gesprochen. Doch ich vermisse sie. Würdet Ihr mir einen Gefallen tun und ihr diesen Brief von mir geben? Ich will sicher sein, dass sie ihn auch erhält.", sourceObjective = "Bringt die leicht zerknitterte Notiz zu Elenia Haydon nahe der Bank in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8901] = { id = 8901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Elenia", description = "Habt Ihr jemals wahre Liebe erfahren, <junger Herr/junge Dame>? Noch vor Kurzem war dies ein Fremdwort für mich, doch dann traf ich dieses junge Mädchen aus Unterstadt, Elenia. Es ist selten für einen Angehörigen meiner Art, sich mit den anderen Völker einzulassen, ganz besonders mit den Verlassenen.\n\nDoch jetzt sind meine Gedanken Tag und Nacht von ihr erfüllt.\n\nWäre es Euch vielleicht möglich, ihr diesen Brief zu überbringen? Ich möchte, dass sie hierher nach Mulgore kommt. Hoffentlich sagt sie ja.", sourceObjective = "Bringt den sorgfältig verfassten Brief zu Elenia Haydon nahe der Bank in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8902] = { id = 8902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Elenia", description = "Zu Lebzeiten hatte ich geschworen, Elenia, meine Jugendliebe, zu meiner Frau zu nehmen. Es ist schon Jahre her, seit ich das letzte Mal an sie denken musste. Doch seit einiger Zeit beherrschen mehr und mehr Gedanken an sie meinen Verstand.\n\nObwohl es eine Ewigkeit her ist, sollte es in unser beider Leben noch etwas Raum für unsere Liebe geben.\n\nIch bin sicher, auch sie wird sich verändert haben. Sei es drum! Wäre es Euch vielleicht möglich, ihr diesen Brief zu überbringen? Ich selbst bin zu nervös, um ihr selbst gegenüberzutreten.", sourceObjective = "Bringt den liebevoll verfassten Brief zu Elenia Haydon nahe der Bank in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8903] = { id = 8903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Liebschaft", description = "Diese Liebesepidemie hat etwas unnatürliches an sich. Die ganze Situation ist ungebührlich, ja ein Schandfleck, und im schlimmsten Fall eine Bedrohung für die Sicherheit der gesamten Allianz.\n\nDenkt doch nur: Was passiert, wenn sämtliche Wachen von dieser seltsamen Krankheit betroffen werden? Irgendetwas muss geschehen.\n\nGeht zu einer der Wachen hier in Sturmwind und seht, ob sie von dieser törichten Epidemie befallen wurde.", sourceObjective = "Besorgt die Karte einer Wache von Sturmwind und bringt sie zu Aristan Mottar in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[8904] = { id = 8904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Liebschaft", description = "Diese Liebesepidemie hat etwas unnatürliches an sich. Die ganze Situation ist abscheulich, und wenn sie erst einmal unsere Verteidigung schwächt, könnte dies zu einer ernsten Bedrohung für uns alle werden.\n\nSchlimm genug, dass bereits ein Großteil unserer Bevölkerung dieses lächerlich säuselnde Verhalten an den Tag legt. Ich denke, selbst unsere Wächter hat es bereits erwischt, dabei sollten sie gegen derartige Einflüsse immun sein.\n\nGeht zu einem der Wächter und seht, ob er von dieser törichten Epidemie befallen wurde.", sourceObjective = "Besorgt eine modrige Karte des Wächters und bringt sie zu Fenstad Argyle in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8905] = { id = 8905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein aufrichtiges Angebot", description = "Seid gegrüßt, {class}. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterquell heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", sourceObjective = "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Wildherzens zu Deliana in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8906] = { id = 8906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein aufrichtiges Angebot", description = "Seid gegrüßt, {class}. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterquell heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", sourceObjective = "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Bestienjägerbindungen zu Deliana in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8907] = { id = 8907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein aufrichtiges Angebot", description = "Seid gegrüßt, {class}. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterquell heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", sourceObjective = "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Bindungen des Magisters zu Deliana in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
