quests[8921] = { id = 8921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ektoplasmadestillierer", description = "Ah, Ihr seid an meinem letzten Projekt interessiert... Dem extradimensionalen Geisterdetektor! Dummerweise sind mir die Geldmittel und Hilfskräfte ausgegangen.\n\nIhr sagt, dass Ihr mir aushelfen wollt? Sehr gut! Zunächst müssen wir einen Apparat bauen, der die Essenz des Todes absaugen kann! Einen Ektoplasmadestillierer zu konstruieren wird allerdings nicht ganz einfach sein, {name}.\n\nIhr müsst mir einen Arkanitwandler, einige große ewige Essenzen und Steinschuppenöl bringen. Außerdem brauche ich noch Vulkanasche aus den Lavatümpeln in der Brennenden Steppe, um einen Filter zu konstruieren.", sourceObjective = "Kehrt mit einem empfindlichen Arkanitwandler, 4 großen ewigen Essenzen, 10 Flaschen Steinschuppenöl, 25 Einheiten Vulkanasche und 40 Gold im Gepäck zu Mux Manamix in Gadgetzan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8922] = { id = 8922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein übernatürlicher Apparat", description = "Ich muss einen Weg finden, mit Anthion Harmon zu sprechen... Oder genauer gesagt mit seinem Geist!\n\nIch kenne da einen Ingenieur, der eine gewisse Faszination für das Übernatürliche hegt. Er behauptet eine Maschine konstruieren zu können, die es ihm erlaubt mit den Toten zu kommunizieren!\n\nDas Blut, dass Ihr gesammelt habt, war für ihn bestimmt. Reist nach Gadgetzan und bringt es ihm als Bezahlung für seine Dienste!", sourceObjective = "Bringt den versiegelten Blutbehälter zu Mux Manamix in Gadgetzan.", sourceObjectiveStatus = "unverified-source-field" }
quests[8923] = { id = 8923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Supernatural Device" }
quests[8924] = { id = 8924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ektoplasmajagd", description = "Ein hervorragendes Stück Ingenieurarbeit, wenn ich das mal selbst so sagen darf! Ich fürchte allerdings, dass Ihr weit umherreisen werden müsst, um die Art schemenhafter Untoten zu finden, die wir benötigen.\n\nIhr müsst verstehen, dass verschiedenen Klimabedingungen Einfluss auf die spektrale Struktur der Toten haben. Die gequälten Nachtelfen in Silithus, die Geister der Hochgeborenen in Winterquell und die Geister und Banshees in den Östlichen Pestländern sollten uns mit den verschiedenen Sorten von Ektoplasma versorgen, die wir benötigen. Stellt auf jeden Fall den Destillierer in der Nähe auf, bevor Ihr sie bekämpft.", sourceObjective = "Benutzt den Ektoplasmadestillierer in der Nähe von schemenhaften Untoten, um 12 Einheiten versengtes Ektoplasma in Silithus, 12 Einheiten gefrorenes Ektoplasma in Winterquell und 12 Einheiten stabiles Ektoplasma in den Östlichen Pestländern zu erhalten. Bringt das Ektoplasma dann mitsamt des Ektoplasmadestillierers zu Mux Manamix in Gadgetzan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8925] = { id = 8925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine portable Energiequelle", description = "Jetzt brauchen wir nur noch eine stabile und portable Energiequelle, um das Ektoplasma aktiv zu halten. Ich habe Gerüchte über einen machtvollen Elementar namens Magmafürst Bokk gehört, dessen Herz ein mächtiger Magmakern ist - eine schier unerschöpfliche Hitzequelle!\n\nMan sagt, dass er sich irgendwo in der Brennenden Steppe südlich des Schwarzfels herumtreibt. Bringt mir den Magmakern und wir werden genug Saft haben, um den extradimensionalen Geisterdetektor zu betreiben!", sourceObjective = "Findet Magmafürst Bokk in der Brennenden Steppe, nehmt seinen Magmakern an Euch und bringt ihn zu Mux Manamix in Gadgetzan.", sourceObjectiveStatus = "unverified-source-field" }
quests[8926] = { id = 8926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die angemessene Entlohnung", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir einen gewöhnlichen Gürtel und Handschuhe, von denen Ihr eine verbesserte Version wünscht. Ich kann Euch versichern, dass die Rüstung, die ich Euch geben werde, von weit höherer Qualität sein wird.", sourceObjective = "Bringt Deliana in Eisenschmiede einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens.", sourceObjectiveStatus = "unverified-source-field" }
quests[8927] = { id = 8927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die angemessene Entlohnung", description = "Ihr habt große Verlässlichkeit bewiesen, {name}. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.", sourceObjective = "Bringt Mokvar in Orgrimmar einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens.", sourceObjectiveStatus = "unverified-source-field" }
quests[8928] = { id = 8928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verschlagener Händler", description = "Der Kern sollte uns mit genügend Energie zum Betreiben des Apparates versorgen, jetzt brauchen wir nur noch einen Brennstab, der diese Energie auch weiterleiten kann, ohne dabei zu schmelzen.\n\nIch habe in Winterquell mal einen Wichtel getroffen, der allerlei exotische Waren im Angebot hatte. Er hatte einen elementaren Brennstab, der einfach perfekt gewesen wäre. Ich könnte mich schwarz ärgern, dass ich den nicht gekauft habe.\n\nEr lebt in einer Höhle nahe dem Zugang zur Flüsternden Schlucht. Schleicht Euch hinein und seht zu, dass Ihr ihn findet.\n\nLasst Euch aber nicht von ihm übers Ohr hauen, zahlt ihm nicht mehr als 40 Goldstücke. Den Preis hat er mir damals angeboten!", sourceObjective = "Sucht den Wichtel in der Höhle in der Nähe der Flüsternden Schlucht im Süden von Winterquell. Kauft ihm einen teufelselementaren Brennstab ab und kehrt zu Mux Manamix in Gadgetzan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8929] = { id = 8929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Anthion", description = "Tja, wir haben wohl keine andere Wahl, als die Erfindung des Goblins auszuprobieren. Man sagt, dass Anthion von den untoten Horden Stratholmes niedergemetzelt wurde, als er versuchte, durch dessen Tore zu schreiten.\n\nVersucht den Apparat dort zu benutzen und herauszufinden, was auch immer Anthion wusste.", sourceObjective = "Benutzt den extradimensionalen Geisterdetektor am Eingang zu Stratholme und sprecht mit dem Geist von Anthion Harmon.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[8930] = { id = 8930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Anthion", description = "Nun denn, {name}. Jetzt müssen wir wohl die Erfindung des Goblins ausprobieren. Man sagt, dass Anthion von den untoten Horden Stratholmes niedergemäht wurde, als er versuchte, durch die Tore zu schreiten.\n\nVersucht den Apparat dort zu benutzen und findet heraus, was Anthion wusste.", sourceObjective = "Benutzt den extradimensionalen Geisterdetektor am Eingang zu Stratholme und sprecht mit dem Geist von Anthion Harmon.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
