quests[8945] = { id = 8945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Bitte eines toten Mannes", description = "Ich werde Euch mit den Informationen, nach denen Ihr verlangt, versorgen, {name}. Aber jetzt gibt es Wichtigeres zu tun.\n\nMeine geliebte Frau wird von Totenschwurs Abschaum gefangen gehalten.\n\nIch war immer dagegen, dass sie sich dem närrischen Kreuzzug der Argentumdämmerung anschließt, aber jetzt ist es zu spät für Schuldgefühle. Ihr müsst das vollbringen, wozu ich nicht fähig war. Ihr müsst Ysida aus den Fängen des Barons befreien!", sourceObjective = "Geht nach Stratholme und befreit Ysida Harmon aus den Fängen von Baron Totenschwur.", sourceObjectiveStatus = "unverified-source-field" }
quests[8946] = { id = 8946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensbeweis", description = "Ein wahrhaft grausames Schicksal. Welche Ironie, dass mein Liebster bei dem Versuch mich zu retten ums Leben gekommen ist. Und dennoch behauptet Ihr, mit ihm sprechen zu können.\n\nBringt ihm dieses Medaillon als Beweis dafür, dass es mir gut geht. Er darf nicht länger in dieser Welt verweilen, mein Herz könnte seinen Schmerz nicht verkraften.\n\nLebet wohl, {name}, ich stehe auf ewig in Eurer Schuld.", sourceObjective = "Bringt Anthion Harmon in den Östlichen Pestländern Ysidas Medaillon.", sourceObjectiveStatus = "unverified-source-field" }
quests[8947] = { id = 8947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions merkwürdige Anforderung", description = "Wir waren uns der Wichtigkeit von Valthalaks Amulett nicht bewusst, also wurde es zusammen mit der restlichen Beute aufgeteilt. Das erste Stück bekam ein Zwerg namens Theldren. Ich habe versucht, es mir von ihm zurückzuholen und er hätte mich fast zu Tode geprügelt. Ihr werdet ihm sein Stück gewaltsam entreißen müssen.\n\nDas Letzte, was ich über ihn hörte, ist, dass er ein Gladiator für die Dunkeleisenzwerge geworden ist. Ihn zum offenen Kampf zu bewegen, dürfte sich jedoch schwierig gestalten.\n\nBringt mir die folgenden Materialien, Ihr werdet sie brauchen.", sourceObjective = "Bringt Anthion Harmon in den Östlichen Pestländern 3 Dunkeleisenbarren, 20 verzaubertes Leder, 3 Mondstoff und 4 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[8948] = { id = 8948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions alter Freund", description = "Theldren würde sich niemals freiwillig einem ehrenhaften Kampf stellen. Deshalb habe ich dieses Banner mit seinem Familienwappen hergestellt.\n\nMit der richtigen Verzauberung belegt, sollte es für ihn eine Provokation darstellen, die er nicht ignorieren kann.\n\nEin alter Kollege von mir namens Falrin weiß, was zu tun ist. Er versteht sich darauf... Leute zu verärgern. Ihr findet ihn in der Bibliothek von Düsterbruch.", sourceObjective = "Bringt Falrin Rankenweber in der Bibliothek von Düsterbruch das unvervollständigte Banner der Provokation.", sourceObjectiveStatus = "unverified-source-field" }
quests[8949] = { id = 8949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falrins Rachefeldzug", description = "Ja, ich bin fürwahr mit der Verzauberung vertraut, die Ihr benötigt, {class}. Aber alles hat seinen Preis, selbst wenn Euch ein alter Freund schickt.\n\nIch hasse und verabscheue meine barbarischen Ogernachbarn von ganzem Herzen. Und nicht nur die, ich hasse die Anhänger von Omokk genauso sehr, wie ich die Anhänger von König Gordok verabscheue.\n\nIch will, dass Ihr sie tötet, und zwar Unmengen von ihnen! Bringt mir die Perlen, die sie um den Hals tragen, als Beweis für Eure Taten. Solltet Ihr dies für mich tun, können wir uns weiter über den Gefallen unterhalten, den Ihr von mir verlangt.", sourceObjective = "Nehmt den Ogern in der Schwarzfelsspitze oder in Düsterbruch 25 Ogerkriegsperlen ab und bringt sie zu Falrin Rankenweber im Athenaeum, der Bibliothek von Düsterbruch.", sourceObjectiveStatus = "unverified-source-field" }
quests[8950] = { id = 8950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verzauberung des Aufhetzers", description = "Es wäre mir ein Leichtes, das Banner mit der von Euch benötigten Verzauberung zu belegen, {name}. Bedauerlicherweise verfüge ich allerdings nicht über die benötigten Materialien, da diese Art der Verzauberung nicht hoch im Kurs steht.\n\nIch werde die Essenz von einem der Eldrethgeisterwesen, die diese Hallen durchstreifen, einige Dunkelrunen aus Scholomance und ein paar große glänzende Splitter benötigen. Bringt mir diese Materialien und ich werde die Verzauberung für Euch vornehmen.", sourceObjective = "Bringt Falrin Rankenweber in Düsterbruch 1 Essenz eines spöttischen Geisterwesens, 4 Dunkelrunen und 8 große glänzende Splitter.", sourceObjectiveStatus = "unverified-source-field" }
quests[8951] = { id = 8951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel des Wildherzens, einem Kilt des Wildherzens und einer Schiftung des Wildherzens zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8952] = { id = 8952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Bestienjägerstiefeln, einer Bestienjägerhose und einem Bestienjägermantel zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8953] = { id = 8953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel des Magisters, Gamaschen des Magisters und einem Mantel des Magisters zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8954] = { id = 8954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel des Lichts, Beinplatten des Lichts, und einer Schiftung des Lichts zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8955] = { id = 8955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Sandalen des Gläubigen, einem Rock des Gläubigen und einem Mantel des Gläubigen zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8956] = { id = 8956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel der Schattenkunst, einer Hose der Schattenkunst und einer Schiftung der Schattenkunst zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8957] = { id = 8957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel der Elemente, einem Kilt der Elemente und Schulterstücken der Elemente zu Mokvar in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8958] = { id = 8958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Sandalen der Furcht, Gamaschen der Furcht und einem Mantel der Furcht zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8959] = { id = 8959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel der Ehre, Beinplatten der Ehre und einer Schiftung der Ehre zu Deliana in Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8960] = { id = 8960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodleys trauriges Schicksal", description = "Wir müssen also die restlichen Stücke des Amuletts wiederbeschaffen? Bodley zu finden, könnte sich als schwierig erweisen. Er begab sich zurück in den Schwarzfels, um die Schwarzfelsspitze zu betreten, und kam nie zurück.\n\nIch würde Euch raten, den Geisterdetektor des Goblins mitzunehmen, denn ich befürchte, ihm könnte etwas Schlimmes zugestoßen sein.", sourceObjective = "Reist zum Schwarzfels und benutzt den extradimensionalen Geisterdetektor, um Bodley nahe der Schwarzfelsspitze zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8961] = { id = 8961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die drei Könige der Flammen", description = "Um Lord Valthalak zu beschwören, müssen wir zunächst die anderen beiden Drittel des Amuletts beschaffen. Und dafür brauchen wir wiederum ein Räuchergefäß und einige ganz spezielle Kohlen, die darin verbrannt werden müssen.\n\nEs gibt drei hochrangige Feuerelementare, von denen wir diese Kohlen bekommen können: Lord Incendius in den Schwarzfelstiefen, Feuerwache Glutseher in der Schwarzfelsspitze und der Fürst der Asche in Silithus. Sammelt die Kohlen aus ihren Überresten auf und kehrt dann mitsamt eines geheiligten Räuchergefäßes zu mir zurück. Ihr könnt das Räuchergefäß von der Argentumdämmerung kaufen, wenn sie Euch wohlwollend gesinnt ist.", sourceObjective = "Bringt Bodley im Schwarzfels Incendius' Pyrophor, Glutsehers Glut, die Asche des Fürsten und ein geheiligtes Räuchergefäß.", sourceObjectiveStatus = "unverified-source-field" }
quests[8962] = { id = 8962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nMor Grauhuf, unser bester Druide, hatte viele enge Freunde im Zirkel des Cenarius, von denen einige den Silithiden zum Opfer gefallen sind. Ihr müsst mir einige Druidenüberreste von den Silithiden beschaffen, die den Bau des Regalschwarms im Südosten von Silithus bewohnen.", sourceObjective = "Bringt Bodley im Schwarzfels einige Druidenüberreste.", sourceObjectiveStatus = "unverified-source-field" }
quests[8963] = { id = 8963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nIsalien, unsere Priesterin, wuchs in Sternenhauch in Winterquell auf. Ihr müsst mir ein Relikt von Sternenhauch von den Frosthagelriesen der Frosthauchschlucht im Süden von Winterquell bringen, die dafür bekannt sind, von Zeit zu Zeit den Norden unsicher zu machen.", sourceObjective = "Bringt Bodley im Schwarzfels ein Relikt von Sternenhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[8964] = { id = 8964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um die Geister meiner verstorbenen Kameraden herbeizurufen.\n\nDie Geschwister, Jarien und Sothos, glaubten fest an die Lehren des Scharlachroten Kreuzzugs. Sie strebten danach, Ritter dieser abscheulichen Organisation zu werden. Geht zu Tyrs Hand, in den Östlichen Pestländern, und beschafft mir ein gleißendes Schwert des Zeloten von den dortigen Prätorianern.", sourceObjective = "Bringt Bodley im Schwarzfels ein gleißendes Schwert des Zeloten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8965] = { id = 8965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir das Räuchergefäß haben und es anzünden können, brauchen wir noch ein paar weitere Dinge, die wir hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nKormok, ein Ogernekromant, der unserem Bund angehörte, liebte es die Seelen der verbannten Toten von der Fegefeuerinsel, nahe der Südküste der Vorgebirge des Hügellands, herbeizurufen. Geht dorthin und beschafft mir etwas Seelenasche der Verbannten von ihren Überresten.", sourceObjective = "Bringt Bodley im Schwarzfels etwas Seelenasche der Verbannten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8966] = { id = 8966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das linke Stück von Lord Valthalaks Amulett", description = "Ein Freund von mir, Mor Grauhuf, war der Erste, der Lord Valthalaks Amulett und dem darin enthaltenen, korrumpierenden Seelenfragment zum Opfer fiel. Nachdem wir Valthalaks Zauberbuch und Amulett gestohlen hatten, flohen wir um unser Leben aus dem oberen Teil der Schwarzfelsspitze. Während unserer überstürzten Flucht fiel Mor in den unteren Teil der Schwarzfelsspitze hinab.\n\nWir erfuhren später, dass er den Fall überlebt hatte und von Kriegsmeister Voone gefangen genommen und gefoltert worden war. Später schlichen sich spektrale Assassine in die Schwarzfelsspitze ein und erschlugen Mor vor Voones Augen.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Mor Grauhuf zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8967] = { id = 8967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das linke Stück von Lord Valthalaks Amulett", description = "Wir erfuhren später, während wir alle unser Bestes taten, um zu überleben, dass Isalien, eine Nachtelfenpriesterin, die unserer Gruppe angehörte, in die Heimatstadt der Urahnen der Nachtelfen zurückgekehrt war - jetzt als Düsterbruch bekannt. Demzufolge, was uns berichtet wurde, zog es sie sowohl aus persönlichen Gründen dorthin zurück, als auch weil sie die Geheimnisse ihres Stücks des Amuletts ergründen wollte.\n\nAllerdings gelang es ihr nicht, dieses Wissen zu erlangen. Wie uns zugetragen wurde, wurde sie am Schrein von Eldretharr von Alzzin dem Wildformer und seinen Schergen in einen Hinterhalt gelockt.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Isalien zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8968] = { id = 8968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das linke Stück von Lord Valthalaks Amulett", description = "Die Geschwister, Jarien und Sothos, beschlossen, sich dem Scharlachroten Kreuzzug anzuschließen, nachdem sich unser Söldnerbund aufgelöst hatte. Das linke Stück von Valthalaks Amulett nahmen sie mit sich. Ich war froh, sie los zu sein, aber jetzt brauchen wir dieses Stück zurück.\n\nUnseren Informationen zufolge, wurden sie vom Obersten Kreuzfahrer Dathrohan höchstpersönlich hingerichtet, da sie die Initiationsriten in seiner Kammer in der Scharlachroten Bastion nicht bestanden hatten. \n\nWie dem auch sei, wir... und damit meine ich Ihr, müssen dieses Stück des Amuletts zurückbekommen.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um die Geister von Jarien und Sothos zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8969] = { id = 8969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das linke Stück von Lord Valthalaks Amulett", description = "Jetzt, wo wir alles beisammen haben was wir benötigen, wird es Zeit uns darüber zu unterhalten, wen Ihr beschwören werdet.\n\nKormok war ganz okay, für einen Oger, bis er sich der Nekromantie zuwandte. Von da ab wurde es für jeden im Bund ganz schön gruselig. Es überraschte also niemanden, dass er mit seinem Stück des Amuletts in sein neues Zuhause verschwand, Scholomance.\n\nAber selbst dort, oder vielleicht gerade dort, war er nicht vor den spektralen Assassinen sicher. Sie erschlugen ihn vor den Augen seines Meisters, Ras Frostraunen.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Kormok zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8970] = { id = 8970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich sehe die Insel Alcaz in Eurer Zukunft", description = "Wie ich schon sagte, {class}, zu meinen Lebzeiten spielte ich mit dem Gedanken, ein Wahrsager zu werden. Aber damit kann man bei Weitem nicht so viel Profit machen, wie Ihr vielleicht denken würdet. Die Wahrsagerei kann nämlich ganz schön gefährlich sein und die Reagenzen sind selten und teuer. Aber ich weiß genug, um den Fundort des letzten Amulettstücks zu erahnen, und somit auch den Geist meines ehemaligen Kameraden.\n\nUnd deshalb benötige ich Eure Hilfe, {name}. Ihr müsst zur Insel Alcaz vor der Küste der Düstermarschen reisen und Bluttang von den Naga der Strashaz, die dort leben, zusammensammeln.", sourceObjective = "Bringt Bodley im Schwarzfels 20 Einheiten Bluttang von den Naga der Strashaz.", sourceObjectiveStatus = "unverified-source-field" }
quests[8971] = { id = 8971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
