quests[8976] = { id = 8976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[8977] = { id = 8977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Deliana", description = "War mir eine Freude, mit Euch zusammenzuarbeiten, {name}. Hier ist das fertige Produkt.\n\nIch hoffe, dass es Euch bei Eurem Unterfangen behilflich sein wird. Verbreitet doch bitte die Kunde über meine hervorragenden Dienste, wenn es Euch nichts ausmacht. Ich hätte nichts gegen mehr Kundschaft einzuwenden.", sourceObjective = "Bringt Deliana in Eisenschmiede den extradimensionalen Geisterdetektor.", sourceObjectiveStatus = "unverified-source-field" }
quests[8978] = { id = 8978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Mokvar", description = "War mir eine Freude, mit Euch zusammenzuarbeiten, {name}. Hier ist das fertige Produkt.\n\nIch hoffe, dass es Euch bei Eurem Unterfangen behilflich sein wird. Verbreitet doch bitte die Kunde über meine hervorragenden Dienste, wenn es Euch nichts ausmacht. Ich hätte nichts gegen mehr Kundschaft einzuwenden.", sourceObjective = "Kehrt mit dem extradimensionalen Geisterdetektor zu Mokvar in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8979] = { id = 8979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fenstads Visionen", description = "Ich denke, ich bin dem Grund für das merkwürdige Verhalten auf die Spur gekommen. Habt Ihr den Duft bemerkt, der in letzter Zeit den Gestank der Kanalisation überlagert? Das neue Duftwasser und Parfüm, das gerade so angesagt ist?\n\nUnsere Gedanken werden durch die Wirkung übelster Alchemie vernebelt.\n\nEs gibt nur einen Weg, um ganz sicher zu sein: Bringt meiner Freundin Apothekerin Zinge einen Flakon von dem Parfüm und dem Duftwasser. Die Königliche Apothekervereinigung wird die Wahrheit ans Licht bringen.\n\nIch werde Euch für Eure Ausgaben entschädigen, sobald Ihr zurückkommt.", sourceObjective = "Bringt 1 Duftwasserflakon und 1 Parfümflakon zu Apothekerin Zinge im Apothekarium von Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8980] = { id = 8980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinges Einschätzung", description = "Das ist in der Tat unerwartet. Es sieht ganz so aus, als ob Fenstad doch noch auf etwas gestoßen sein könnte. Ich habe Spuren von Substanzen gefunden, die in Gedanken beinflussenden Tränken Verwendung finden.\n\nEs ist nicht ungewöhnlich, dass man in Parfüm derartige Spuren auffindet, allerdings sind einige der Zutaten, die ich in den Düften finden konnte, doch recht... merkwürdig. Es handelt sich hierbei um Alchemiekünste, die nur den Erfahrensten vorbehalten sind, so wie die Mitglieder der Königlichen Apothekervereinigung.", sourceObjective = "Kehrt zu Fenstad Argyle außerhalb der Bank von Unterstadt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8981] = { id = 8981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschenkübergabe" }
quests[8982] = { id = 8982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgung der Spur", description = "Wir müssen unbedingt herausfinden, wer der Lieferant ist. Ich habe sie erst kürzlich dabei beobachtet, wie sie einen Parfümflakon in ihrem Bündel verstaute. Sie sagte mir, dass sie es von Norman, dem Gastwirt, erworben hat.", sourceObjective = "Sprecht mit Gastwirt Norman in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8983] = { id = 8983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgung der Spur", description = "Ist etwas nicht in Ordnung mit meiner Ware? Nun, ich habe noch nie so viele Leute gesehen, die so sehr nach einer Sache verlangt haben.\n\nIch habe meine Bestände von einer Händlerin namens Mara Rennick. Sie ist neu in der Stadt.\n\nSie erwähnte, dass sie noch einige Waren beim Schneider im Magieviertel abzuliefern hätte.", sourceObjective = "Sprecht mit Mara Rennick bei der Schneiderei im Magieviertel von Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8984] = { id = 8984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lüftung des Geheimnisses", description = "Hört mal, die Taten eines abtrünnigen Apothekers sind nicht mein Problem. Sollte er tatsächlich unsere Sache untergraben, werde ich die Erste sein, die Euch die richtige Richtung weist.\n\nSollte er unschuldig sein, wird er nichts zu verbergen haben, oder?\n\nIch habe meine Ware beim Apotheker Staffron Lerent erworben. Er arbeitet im Vorgebirge des Hügellands, irgendwo hinter dem Rabenholdtanwesen. Ehrlich gesagt, kam er mir etwas komisch vor.", sourceObjective = "Findet Apotheker Staffron Lerent hinter dem Rabenholdtanwesen im Vorgebirge des Hügellands.", sourceObjectiveStatus = "unverified-source-field" }
quests[8985] = { id = 8985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nIsalien, unsere Priesterin, wuchs in Sternenhauch in Winterquell auf. Ihr müsst mir ein Relikt von Sternenhauch von den Frosthagelriesen der Frosthauchschlucht im Süden von Winterquell bringen, die dafür bekannt sind, von Zeit zu Zeit den Norden unsicher zu machen.", sourceObjective = "Bringt Bodley in der Schwarzfelsspitze ein Relikt von Sternenhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[8986] = { id = 8986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nMor Grauhuf, unser bester Druide, hatte viele enge Freunde im Zirkel des Cenarius, von denen einige den Silithiden zum Opfer gefallen sind. Ihr müsst mir einige Druidenüberreste von den Silithiden beschaffen, die den Bau des Regalschwarms im Südosten von Silithus bewohnen.", sourceObjective = "Bringt Bodley im Schwarzfels einige Druidenüberreste.", sourceObjectiveStatus = "unverified-source-field" }
quests[8987] = { id = 8987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nDie Geschwister, Jarien und Sothos, glaubten fest an die Lehren des Scharlachroten Kreuzzugs. Sie strebten danach, Ritter dieser abscheulichen Organisation zu werden. Geht zu Tyrs Hand, in den Östlichen Pestländern, und beschafft mir ein gleißendes Schwert des Zeloten von den dortigen Prätorianern.", sourceObjective = "Bringt Bodley im Schwarzfels ein gleißendes Schwert des Zeloten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8988] = { id = 8988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist, um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nKormok, ein Ogernekromant, der unsererm Bund angehörte, liebte es die Seelen der verbannten Toten von der Fegefeuerinsel, nahe der Südküste der Vorgebirge des Hügellands, herbeizurufen. Geht dorthin und beschafft mir etwas Seelenasche der Verbannten von ihren Überresten.", sourceObjective = "Bringt Bodley im Schwarzfels etwas Seelenasche der Verbannten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8989] = { id = 8989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das rechte Stück von Lord Valthalaks Amulett", description = "Ein Freund von mir, Mor Grauhuf, war der Erste, der Lord Valthalaks Amulett und dem darin enthaltenen, korrumpierenden Seelenfragment zum Opfer fiel. Nachdem wir Valthalaks Zauberbuch und Amulett gestohlen hatten, flohen wir um unser Leben aus dem oberen Teil der Schwarzfelsspitze. Während unserer überstürzten Flucht fiel Mor in den unteren Teil der Schwarzfelsspitze hinab.\n\nWir erfuhren später, dass er den Fall überlebt hatte und von Kriegsmeister Voone gefangen genommen und gefoltert worden war. Später schlichen sich spektrale Assassine in die Schwarzfelsspitze ein und erschlugen Mor vor Voones Augen.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Mor Grauhuf zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8990] = { id = 8990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das rechte Stück von Lord Valthalaks Amulett", description = "Wir erfuhren später, während wir alle unser Bestes taten, um zu überleben, dass Isalien, eine Nachtelfenpriesterin, die unserer Gruppe angehörte, in die Heimatstadt der Urahnen der Nachtelfen zurückgekehrt war - jetzt als Düsterbruch bekannt. Demzufolge, was uns berichtet wurde, zog es sie sowohl aus persönlichen Gründen dorthin zurück, als auch weil sie die Geheimnisse ihres Stücks des Amuletts ergründen wollte.\n\nAllerdings gelang es ihr nicht, dieses Wissen zu erlangen. Wie uns zugetragen wurde, wurde sie am Schrein von Eldretharr von Alzzin dem Wildformer und seinen Schergen in einen Hinterhalt gelockt.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Isalien zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8991] = { id = 8991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das rechte Stück von Lord Valthalaks Amulett", description = "Die Geschwister, Jarien und Sothos, beschlossen, sich dem Scharlachroten Kreuzzug anzuschließen, nachdem sich unser Söldnerbund aufgelöst hatte. Das rechte Stück von Valthalaks Amulett nahmen sie mit sich. Ich war froh, sie los zu sein, aber jetzt brauchen wir dieses Stück zurück.\n\nUnseren Informationen zufolge, wurden sie vom Obersten Kreuzfahrer Dathrohan höchstpersönlich hingerichtet, da sie die Initiationsriten in seiner Kammer in der Scharlachroten Bastion nicht bestanden hatten. \n\nWie dem auch sei, wir... und damit meine ich Ihr, müssen dieses Stück des Amuletts zurückbekommen.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um die Geister von Jarien und Sothos zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8992] = { id = 8992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das rechte Stück von Lord Valthalaks Amulett", description = "Jetzt, wo wir alles beisammen haben, was wir benötigen, wird es Zeit, uns darüber zu unterhalten, wen Ihr als Nächstes beschwören werdet.\n\nKormok war für einen Oger ganz okay, bis er sich der Nekromantie zuwandte. Von da ab wurde es für jeden im Bund ganz schön gruselig. Es überraschte also niemanden, dass er mit seinem Stück des Amuletts in sein neues Zuhause verschwand, Scholomance.\n\nAber selbst dort, oder vielleicht gerade dort, war er nicht vor den spektralen Assassinen sicher. Sie erschlugen ihn vor den Augen seines Meisters, Ras Frostraunen.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Kormok zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Schwarzfels zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8993] = { id = 8993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschenkübergabe" }
quests[8994] = { id = 8994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Vorbereitungen", description = "Wir sind nun beinah bereit, {class}. Ich brauche nur noch einige weitere Komponenten, um das Räuchergefäß darauf abzustimmen, Lord Valthalak herbeizurufen.\n\nFür den Anfang würde ich Euch darum bitten, Euch in die Schwarzfelsspitze zu begeben und die dort heimischen Orcs zu töten. Ihre Armschienen enthalten Metallspuren, die ich benötigen werde. Da diese Armschienen nur Spuren des Metalls enthalten, werde ich eine Menge von ihnen benötigen. Um den Abstimmungsprozess abzuschließen, brauche ich weiterhin noch ein Fläschchen der obersten Macht.\n\nViel Glück, {name}!", sourceObjective = "Bringt Bodley im Schwarzfels 40 Schwarzfelsarmschienen und ein Fläschchen der obersten Macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[8995] = { id = 8995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mea Culpa, Lord Valthalak", description = "Die nötigen Vorbereitungen sind nun getroffen, {name}.\n\nZu seinen Lebzeiten bewohnte Lord Valthalak die Kammer, in der sich nun die Bestie aufhält. Geht dorthin und benutzt dann das Räuchergefäß der Beschwörung, um Lord Valthalak herbeizurufen. Es wird ihn wiederbeleben, also werdet Ihr ihn erneut töten müssen. Es wäre sinnvoll, zuerst die Bestie zu erledigen. Bringt außerdem genug Kameraden mit, um Euch durch den oberen Teil der Schwarzfelsspitze zu kämpfen.\n\nBenutzt, sobald Ihr ihn ausgeschaltet habt, das Amulett bei seiner Leiche. Nachdem seine Seele wieder vollständig ist, wird er es vermutlich zurückverlangen.\n\nViel Glück!", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um Lord Valthalak zu beschwören. Macht ihn unschädlich und benutzt dann Lord Valthalaks Amulett bei seiner Leiche. Danach werdet Ihr dem Geist von Lord Valthalak sein Amulett zurückgeben müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8996] = { id = 8996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Bodley", description = "Ich werde Euch Eure Unverschämtheit dieses eine Mal vergeben, {class}, da Ihr heute eine noble Tat vollbracht habt. Ihr habt mich wieder mit dem Rest meiner gestohlenen Seele vereint. Obgleich Eurer offensichtlich schwachen Natur, {race}, habt Ihr den Mut bewiesen, über den jene, die es wagten mich zu bestehlen, nicht verfügten und vermutlich niemals werden.\n\nKehret schnell zu ihnen zurück, bevor ich es mir anders überlege und Euch dort niederstrecke, wo Ihr steht. Kehret zurück und richtet ihnen aus, dass sie vor mir sicher sind... Momentan zumindest.", sourceObjective = "Bringt das Räuchergefäß der Beschwörung zurück zu Bodley im Schwarzfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[8997] = { id = 8997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Anfang", description = "Ich denke, nun wird es Zeit Lebewohl zu sagen, mein Freund. Ich werde immer hier sein, falls Ihr von Zeit zu Zeit mal mit mir reden wollt. Vielleicht ja, während Ihr auf Eure Kameraden wartet um der Schwarzfelsspitze einen Besuch abzustatten.\n\nGeht, bevor ich noch anfange zu heulen. Geht zu Deliana in Eisenschmiede zurück und erzählt ihr, was vorgefallen ist.", sourceObjective = "Sprecht mit Deliana am Hohen Sitz von Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8998] = { id = 8998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Anfang", description = "Ich denke, nun wird es Zeit Lebewohl zu sagen, mein Freund. Ich werde immer hier sein, falls Ihr von Zeit zu Zeit mal mit mir reden wollt. Vielleicht ja, während Ihr auf Eure Kameraden wartet um der Schwarzfelsspitze einen Besuch abzustatten.\n\nGeht, bevor ich noch anfange zu heulen. Geht zu Mokvar in Orgrimmar zurück und erzählt ihm, was vorgefallen ist.", sourceObjective = "Sprecht mit Mokvar in der Feste Grommash im Tal der Weisheit von Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8999] = { id = 8999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, {name}! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", sourceObjective = "Gebt Deliana Eure Gugel des Wildherzens und Eure Weste des Wildherzens.", sourceObjectiveStatus = "unverified-source-field" }
quests[9000] = { id = 9000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, {name}! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", sourceObjective = "Gebt Deliana Eure Bestienjägerkappe und Eure Bestienjägertunika.", sourceObjectiveStatus = "unverified-source-field" }
