quests[9050] = { id = 9050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handgelenksschützer der Erlösung", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.", sourceObjective = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Paar Handgelenksschützer der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Handgelenksschützer, 6 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9051] = { id = 9051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftexperiment", description = "Das Gift, das Ihr mir geholfen habt zu entwickeln, ist für einen bestimmten Zweck gedacht. Die mächtigen Teufelssaurier des Kraters erschweren mir die Jagd und das Überleben. Selbst wenn ich über die nötige Stärke verfügen würde, einen Teufelssaurier zu erlegen, würde einfach nur ein anderer sein Territorium beanspruchen.\n\nNehmt diesen vergifteten Widerhaken und stecht ihn tief in einen lebenden Teufelssaurier. Das Gift sollte ihn ruhigstellen, aber ich bin mir nicht sicher, wie lange es dauern wird, bis es wirkt...", sourceObjective = "Stecht einen Teufelssaurier mit dem Teufelssaurierhaken und kehrt danach zu Torwa Pfadfinder im Krater von Un'Goro zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9052] = { id = 9052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutblütengift", description = "Ich würde Euch darum bitten, mir dabei behilflich zu sein, ein spezielles Gift zu entwickeln, um eine der mächtigsten Kreaturen des Kraters ruhigzustellen. Es ist nicht tödlich und nur <ein/eine:c> {class} mit scharfen Augen kann die nötigen Zutaten dafür erspähen.\n\nDie Blutkappenpilze wachsen in den Blutblütensprösslingen, die überall im Krater anzufinden sind. Gorishistachel könnt Ihr von den Insekten erhalten, die in der und um die Wuchernde Narbe herum heimisch sind. Sie befindet sich im südlichen Teil des Kraters.", sourceObjective = "Sammelt 8 Blutkappenpilze und 8 Gorishistachel und kehrt zu Torwa Pfadfinder im Krater von Un'Goro zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9053] = { id = 9053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bessere Zutat", description = "Genau wie ich befürchtet hatte - das Gift ist einfach zu schwach für eine solch mächtige Kreatur.\n\nUm ein Gift von ausreichender Potenz zu entwickeln, werdet Ihr Euch auf den Grund des Tempels von Atal'Hakkar begeben müssen. Enträtselt dort das Geheimnis des Altars und nehmt dem Wächter eine Fäulnisranke ab. Der Tempel ist gefährlich und es wird vermutlich erforderlich sein, Gefährten mitzubringen.\n\nKehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Beschafft Euch eine Fäulnisranke von dem Wächter auf dem Grund des Versunkenen Tempels und kehrt zu Torwa Pfadfinder zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9054] = { id = 9054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tunika des Gruftpirschers", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", sourceObjective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Tunika des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9055] = { id = 9055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinschützer des Gruftpirschers", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", sourceObjective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Beinschützer des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinschützer, 20 kampfzerschlissene Kettenstücke, 3 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9056] = { id = 9056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfstück des Gruftpirschers", description = "Ich habe eine Verwendung für den Panzer des Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", sourceObjective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Kopfstück des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihtes Kopfstück, 15 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 2 Nexuskristalle.", sourceObjectiveStatus = "unverified-source-field" }
quests[9057] = { id = 9057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiftung des Gruftpirschers", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", sourceObjective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Schiftung des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Schiftung, 12 kampfzerschlissene Kettenstücke, 2 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
