quests[9059] = { id = 9059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handschützer des Gruftpirschers", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", sourceObjective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Handschützer des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Handschützer, 8 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9060] = { id = 9060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurt des Gruftpirschers", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", sourceObjective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Gurt des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Gurt, 8 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 3 Nexuskristalle.", sourceObjectiveStatus = "unverified-source-field" }
quests[9061] = { id = 9061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handgelenksschützer des Gruftpirschers", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", sourceObjective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Paar Handgelenksschützer des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Handgelenksschützer, 6 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9062] = { id = 9062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgeweichte Seiten", description = "Diese verdammten Getriebenen können recht schnell rennen, wenn sich ihnen einer entgegenstellt. Nun, das soll uns nun erstmal egal sein. Ich muss den Foliant der Elementarmagie meines Instrukteurs finden.\n\nIch bin mir ganz sicher, dass ich gesehen habe, wie ihn einer dieser Feiglinge in den Fluss geworfen hat, aber ich kann ihn einfach nicht ausfindig machen. Ich könnte noch ein Paar Augen gebrauchen. Solltet Ihr ihn finden, lasse ich auch ein paar Münzen springen.", sourceObjective = "Lehrling Meledor im Immersangwald möchte, dass Ihr im Gewässer unterhalb der nahegelegenen Brücke sucht und ihm Antheols Foliant der Elementarmagie bringt.", progress = "Kein Glück? Na dann, sucht weiter. Das Buch ist überaus wichtig, {class}.", completion = "Das Buch ist völlig aufgeweicht. Instrukteur Antheol wird alles andere als erfreut sein.\n\nHier, nehmt das Geld. Ich habe eine Idee.", sourceObjectiveStatus = "unverified-source-field" }
quests[9063] = { id = 9063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torwa Pfadfinder", description = "Ein Jäger namens Torwa Pfadfinder hat die Hilfe eines Druiden angefordert. Er sagte, dass nur einer von uns über den nötigen Respekt für die Natur und die Fähigkeiten verfügen würde, um ihm zu helfen.\n\nEs gibt einen Pfad, der den Krater von Un'Goro und die Tanariswüste verbindet. Ihr werdet Torwa nahe dem Punkt finden, an dem der Pfad in den Krater hineinführt.", sourceObjective = "Sprecht im Krater von Un'Goro mit Torwa Pfadfinder.", sourceObjectiveStatus = "unverified-source-field" }
quests[9064] = { id = 9064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sache ausbaden", description = "Antheol wird aus der Haut fahren, wenn er erfährt, dass sein Buch ruiniert ist. Ich würde Euch gerne etwas vorschlagen; keine Sorge, es wird die Mühe wert sein.\n\nBringt ihm das Buch und erzählt ihm nichts über den Vorfall. Sollte er Euch fragen, so sagt ihm einfach, dass Ihr das Buch in eine Pfütze habt fallenlassen. Ihr seid kein direkter Untergebener von ihm, also kann er nicht viel ausrichten.\n\nAntheol hält seine Vorlesungen beim Stillwispertümpel, südöstlich von Silbermond. Ihr werdet uns diesen Gefallen doch tun, oder? Ich werde Euch auch reichlich dafür belohnen!", sourceObjective = "Bringt Antheols Foliant der Elementarmagie zu Instrukteur Antheol beim Stillwispertümpel im Immersangwald.", progress = "Warum unterbrecht Ihr meine Vorlesung, {class}?", completion = "Ihr sagt, dass Euch diese zwei unfähigen Narren bestochen haben, damit Ihr mich anlügt? Es war richtig von Euch, zu mir zu kommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9065] = { id = 9065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pattymack-Spezial", sourceObjective = "Stell sicher, dass du den Turm zerstörst!", sourceObjectiveStatus = "unverified-source-field" }
quests[9066] = { id = 9066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disziplin muss sein", description = "Ich hoffe, dass Ihr heute eine wichtige Lektion gelernt habt, {name}. Vertraut niemandem, der für Euch lügen soll.\n\nIch möchte, dass Ihr jetzt zu meinen zwei dusseligen Schülern geht und sie mit diesem Stab angemessen bestraft. Meine Magie verrät mir, dass Ihr sie an der Straße gen Westen auf der anderen Seite der Todesschneise finden werdet.\n\nKommt anschließend zu mir zurück. Ich werde Euch eine kleine Belohnung für Eure Mühe geben.", sourceObjective = "Wendet Antheols Disziplinarsstab bei seinen zwei Schülern an: Lehrling Ralen und Lehrling Meledor. Kehrt anschließend mit dem Stab zu Antheol beim Stillwispertümpel im Immersangwald zurück.", progress = "Habt Ihr meine Anweisungen befolgt, {name}?", completion = "Ausgezeichnete Arbeit, {name}. Keine Sorge, sie werden nicht auf Dauer in dieser Gestalt ausharren müssen. Allerdings geht es mit ihrer Lehre erst dann weiter, wenn sie es sich verdient haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9067] = { id = 9067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Feier ist nie zu Ende", description = "Ich liebe es Feste zu feiern... mein bescheidener Beitrag, die Herrlichkeit von Quel'Thalas zu würdigen!\n\nAllerdings befinde ich mich in einer misslichen Lage... ich brauche Euch, um mir mehr Festvorräte zu besorgen.\n\nBringt mir eine Flasche Bester Sonnentropfen von Kellermeister Sonnentropfen in Silbermond und köstliche Bachtatzenhäppchen von Zalene Morgenlicht bei der Zuflucht der Weltenwanderer. Und wenn Ihr schon einmal dabei seid, könnt Ihr auch gleich meine Feuerwerkslieferung bei Halis Morgenwandler im Dörfchen Morgenluft abholen.\n\nBeeilt Euch!", sourceObjective = "Besorgt eine Flasche Bester Sonnentropfen, Bachtatzenhäppchen und ein Feuerwerksbündel und bringt alles zu Lord Saltheril in Saltherils Hafen im Immersangwald.", progress = "Habe ich Euch nicht gerade losgeschickt, um mehr Festvorräte zu beschaffen? Oh, also man kann wirklich nicht von mir erwarten, dass ich mich an jedes Gesicht erinnere, nicht wahr? Ich treffe so viele... interessante Leute.\n\nWas ist Euer Anliegen?", sourceObjectiveStatus = "unverified-source-field" }
quests[9068] = { id = 9068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tunika des Erdspalters", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen, sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.", sourceObjective = "Rimblat Erdspalter bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Tunika des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9069] = { id = 9069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinschützer des Erdspalters", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen, sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.", sourceObjective = "Rimblat Erdspalter bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Beinschützer des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinschützer, 20 kampfzerschlissene Kettenstücke, 3 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
