quests[9076] = { id = 9076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getriebener Rädelsführer", description = "Die Getriebenen sind so auf den Verzehr von fauler Magie konzentriert, sie haben nicht einmal gemerkt, dass wir den Großteil unserer Waffen wieder an uns gebracht haben. Wir können uns allerdings nicht auf ihren Zustand der Benommenheit verlassen. Es ist an der Zeit für einen ausschlaggebenden Angriff. Lasst uns anhand ihres Anführers Aldaron ein Exempel statuieren. Er wurde im obersten Teil des Gebäudes beim Ankerplatz gesichtet. Bringt mir seinen Kopf, ich werde Euch entsprechend entlohnen.", sourceObjective = "Bringt Aldarons Kopf zu Velendris Weißflor nahe des Ankerplatzes der Sonnensegel im Immersangwald.", progress = "Nun, habt Ihr seinen Kopf? Verschwendet nicht meine Zeit, {name}.", completion = "Ihr habt ihn also doch noch bezwungen! Meine Männer hatten ihn natürlich schon geschwächt.\n\nDas war ein Scherz, {class}. Ihr habt Euch gut geschlagen. Wenn Ihr weiterhin eine weiße Weste behaltet, werdet Ihr Euch noch einen Namen machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9077] = { id = 9077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brustplatte der Knochensense", description = "Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.\n\nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung, sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.", sourceObjective = "Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Brustplatte der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Brustplatte, 25 kampfzerschlissene Lederstücke, 2 Arkanitbarren und 6 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
