quests[9084] = { id = 9084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armschienen der Knochensense", description = "Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.\n\nGeht nach Naxxramas, der schwebenden Metropole des Todes, hier oben im Himmel, und sucht nach entweihter Rüstung, sowie kampfzerschlissenen Rüstungsstücken. Bringt alles mitsamt der Materialien zum Zusammenfügen zurück und Ihr bekommt Eure Knochensensenrüstung. Oh, Ihr werdet mich natürlich auch für meine Mühen entschädigen müssen... Ich stelle die Knochen zur Verfügung.", sourceObjective = "Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Armschienen der Knochensense anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Armschienen, 6 kampfzerschlissene Lederstücke, 1 Arkanitbarren, 2 geschmeidige unverwüstliche Bälge und 10 Goldstücke.", sourceObjectiveStatus = "unverified-source-field" }
quests[9085] = { id = 9085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten der Verdammnis", description = "Nachdem Ihr die Verteidigung der Beschwörungskreise der Geißel ausgeschaltet habt, müsst Ihr den Akolythen, die sie beschützen, gegenübertreten.\n\nIn Wirklichkeit handelt es sich hier keineswegs um richtige Wesen, sondern um Schatten, die zu den beängstigendsten Kreaturen des Lichkönigs zählen. Sie können mithilfe der nekrotischen Runen, die sie bei sich tragen, Gestalt annehmen und dann mit Magie oder dem Einsatz von Waffen zerstört werden.", sourceObjective = "Geht zu einem Beschwörungskreis und tötet einen Schatten der Verdammnis. Kehrt dann zu Kommandant Thomas Helleran bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9086] = { id = 9086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tunika des Traumwandlers", description = "Im letzten Krieg sind zahllose Helden umgekommen und auch heute fallen der Geißel täglich noch viele weitere Streiter zum Opfer. Den Körpern der Gefallenen werden die Rüstungen entwendet und zurück nach Naxxramas gebracht, um dort für unbekannte Zwecke missbraucht zu werden.\n\nMacht die entweihten Rüstungsteile und kampfzerschlissene Rüstungsstücke ausfindig. Besorgt mir zusätzlich die anderen Bestandteile, die ich benötige, dann werde ich eine Rüstung des Traumwandlers für Euch anfertigen.", sourceObjective = "Rayne bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Tunika des Traumwandlers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Lederstücke, 6 geschmeidige unverwüstliche Bälge und 2 Nexuskristalle.", sourceObjectiveStatus = "unverified-source-field" }
