quests[9103] = { id = 9103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Robe des verseuchten Herzens", description = "Ich mache Euch nichts vor, Wurm. Die Finsternis, die die Rüstung des verseuchten Herzens erfüllt, könnte uns beide mit Leichtigkeit zerstören. Dies erklärt den äußerst hohen Preis. Sollte ich sterben, so werde ich zumindest als reicher Mann dahinscheiden.\n\nEs kümmert mich einen Ogerdreck als was Ihr sterbt, Hauptsache Ihr macht, was ich von Euch verlange. Bringt mir die benötigten Dinge und wir werden beide davon profitieren - oder sterben; aber das habe ich ja bereits erklärt...", sourceObjective = "Mataus der Zornwirker bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Robe des verseuchten Herzens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Robe, 25 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.", sourceObjectiveStatus = "unverified-source-field" }
