quests[9111] = { id = 9111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Robe des Glaubens", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", sourceObjective = "Vater Inigo Montoy bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Robe des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Robe, 25 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.", sourceObjectiveStatus = "unverified-source-field" }
