quests[9118] = { id = 9118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindungen des Glaubens", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", sourceObjective = "Vater Inigo Montoy bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Bindungen des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Bindungen, 6 kampfzerschlissene Stoffstücke, 1 Arkankristall und 1 Nexuskristall.", sourceObjectiveStatus = "unverified-source-field" }
quests[9119] = { id = 9119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwischenfall beim Sanktum des Westens", description = "Da Ihr schon mal hier seid, {name}, habe ich eine Bitte an Euch. Leybewahrerin Velanias Lehrling kam vorhin vorbei und bat um Unterstützung. Beim Sanktum des Westens kam es offenbar zu einem Zwischenfall. Ich bin gerade zu sehr mit der... Unterhaltung... unserer Zwergengäste beschäftigt. Vielleicht könnt Ihr ja aushelfen. Ihr findet das Sanktum des Westens südwestlich von hier.", sourceObjective = "Sprecht mit Leybewahrerin Velania beim Sanktum des Westens im Immersangwald.", completion = "Seht Euch um. Hier stimmt so einiges nicht.\n\nBeim Sanktum des Westens kam es zu einem schweren Zwischenfall. Lasst uns alles Erdenkliche tun, um Schlimmeres zu verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9120] = { id = 9120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Niedergang Kel'Thuzads", description = "Das Phylakterium ist alles, was vom Herrscher Naxxramas' übrig bleibt. Nach Eurem pflichtgemäßen Ermessen, müsstet Ihr das Phylakterium zerstören, um somit einem erneuten Aufbäumen des Lichs vorzubeugen. Glücklicherweise hört Ihr nur selten auf Eure innere Stimme der Vernunft.\n\nBei der Kapelle des Hoffnungsvollen Lichts wird Euch irgendjemand mit Sicherheit ein Vermögen für dieses Artefakt bezahlen. Wen kümmert es schon, ob Kel'Thuzad eines Tages wieder von Neuem erstarkt?", sourceObjective = "Bringt Kel'Thuzads Phylakterium zu der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9121] = { id = 9121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zitadelle des Schreckens - Naxxramas", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch, dort hineinzugelangen, von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichtegemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mithilfe von arkaner Tarnung Zugang verschaffen können – einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Da es an Eurer Hingabe für die Ziele der Argentumdämmerung noch etwas mangelt, {name}, wird der Preis hoch sein. Es steht Euch frei, abzulehnen und noch einmal für einen günstigeren Preis wiederzukehren, sobald Euer Ruf respektvoll oder ehrfürchtig ist.", sourceObjective = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 Arkankristalle, 2 Nexuskristalle, 1 rechtschaffene Kugel und 60 Goldstücke. Euer Ruf bei der Argentumdämmerung muss außerdem wohlwollend sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9122] = { id = 9122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zitadelle des Schreckens - Naxxramas", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch, dort hineinzugelangen, von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichtegemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mithilfe von einer Art dauerhaften arkanen Tarnung Zugang verschaffen können – einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Diese Tarnung ist allerdings sehr kostspielig. Da Eure Hingabe für die Ziele der Argentumdämmerung bewundernswert ist, sind wir gewillt, einige dieser Kosten für Euch zu übernehmen.", sourceObjective = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 2 Arkankristalle, 1 Nexuskristall und 30 Goldstücke. Euer Ruf bei der Argentumdämmerung muss außerdem respektvoll sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9123] = { id = 9123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zitadelle des Schreckens - Naxxramas", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch, dort hineinzugelangen, von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichtegemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mithilfe von einer Art dauerhaften arkanen Tarnung Zugang verschaffen können – einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Diese Tarnung ist allerdings sehr kostspielig. Da Eure Hingabe für die Ziele der Argentumdämmerung jedoch unerschütterlich ist, werden wir Euch sämtliche Kosten erlassen.", sourceObjective = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird Euch die arkane Tarnung kostenfrei gewähren. Euer Ruf bei der Argentumdämmerung muss ehrfürchtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9124] = { id = 9124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was man für Gruftpirscherrüstung braucht...", description = "Würdet Ihr Euch gerne eine dieser glänzenden Münzen verdienen?\n\n<Leopold hält ein Insigne des Kreuzzugs in die Höhe.>\n\nIch habe ein kleines Problem, bei dem Ihr mir vielleicht behilflich sein könntet, {name}. Seht Ihr, ich fertige Gruftpirscherrüstung für diejenigen an, die dämlich genug sind, um sich nach Naxxramas zu wagen. Zwar versorgen sie mich mit den wichtigsten Bestandteilen für die Rüstung versorgen, mir gehen aber ständig die Teile von Gruftbestien aus. Bringt mir einen Schwung dieser Teile und ich werde Euch dafür mit einem Insigne bezahlen - einlösbar bei dem Rüstmeister.", sourceObjective = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Teile einer Gruftbestie.", sourceObjectiveStatus = "unverified-source-field" }
quests[9125] = { id = 9125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teile einer Gruftbestie" }
quests[9126] = { id = 9126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochensensenjagd", description = "Don Julios Muster für die Rüstung der Knochensense benötigt Knochenfragmente - ein Menge Knochenfragmente. Diejenigen, die verrückt genug sind, um sich nach Naxxramas zu wagen, versorgen mich bereits mit den wichtigsten Bestandteilen für die Rüstung. Allerdings halte ich stets nach weiteren Knochenfragmenten Ausschau.\n\nWas denkt Ihr? Würdet Ihr Euch gerne die Hände schmutzig machen und dabei ein paar Anhänger der Geißel vernichten? Hierbei kommt jeder gut davon.", sourceObjective = "Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Knochenfragmente.", sourceObjectiveStatus = "unverified-source-field" }
quests[9127] = { id = 9127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenfragmente" }
quests[9128] = { id = 9128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elementargleichung", description = "Seid gegrüßt, Abenteurer! Hättet Ihr Interesse an Arbeit? Wer für mich arbeitet, wird mit Insignien bezahlt. Diese Insignien können beim Rüstmeister für mächtige Gegenstände eingetauscht werden.\n\nEure Aufgabe besteht darin, mir so viele Kerne der Elemente zu bringen, wie Ihr tragen könnt. Je mehr, umso besser!\n\nIhr findet sie bei Elementaren verschiedenster Form und Größe, wie es sie überall in unserer Welt gibt.", sourceObjective = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Kerne der Elemente.", sourceObjectiveStatus = "unverified-source-field" }
quests[9129] = { id = 9129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kern der Elemente" }
quests[9130] = { id = 9130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waren von Silbermond", description = "Ah, <ein Freiwilliger/eine Freiwillige>! Uns gehen hier langsam die Vorräte aus, aber Silbermond hat uns Unterstützung in Form von Hilfsgütern zugesichert. Hier kommt Ihr ins Spiel.\n\nBringt diesen Frachtbrief zu Himmelsmeister Morgenhell. Er wird Euch weiter Auskunft darüber geben, wie Ihr am besten nach Silbermond gelangt.", sourceObjective = "Bringt Sathiels Frachtbrief zu Himmelsmeister Morgenhell in Morgenluft.", progress = "Ja, was gibt's?", completion = "Sathiel möchte, dass Ihr nach Silbermond geht und ihre Waren zurückbringt, was? Kein Problem, ich kann Euch schnell dorthin bringen... gegen eine kleine Gebühr, versteht sich.", sourceObjectiveStatus = "unverified-source-field" }
